-- Amazon offers for the ranking pages (/es/mejores/…, /de/vergleich/…). Generated from src/content/rankings/*.md on 2026-10-29.
-- Applied to nutrimetrics-db by hand (idempotent). Product IDs 9101+ = ranking products (ES first seen 91xx, DE first seen 92xx).
-- Amazon prices are NOT stored or shown (Associates rules: prices only via the Creators API): price = 0 means 'not tracked'.
-- /go/{offerId} adds the Associates tag from the Worker secrets AMAZON_TAG_ES / AMAZON_TAG_DE once they exist.
PRAGMA foreign_keys = ON;

ON CONFLICT(id) DO UPDATE SET name = excluded.name, network = excluded.network, ships_from = excluded.ships_from, active = excluded.active;

ON CONFLICT(id) DO UPDATE SET brand = excluded.brand, name = excluded.name, pack_label = excluded.pack_label, verified = excluded.verified, source_url = excluded.source_url, updated_at = datetime('now');

ON CONFLICT(id) DO UPDATE SET product_id = excluded.product_id, retailer_id = excluded.retailer_id, country = excluded.country, merchant_url = excluded.merchant_url, checked_at = excluded.checked_at;
